cat > src/cli/explain.ts <<'EOF'
const FAILURE_CODES: Record<string, string> = {
  F1: 'edited existing tests',
  F2: 'never ran tests',
  F3: 'broke the existing test suite',
  F4: 'stopped early',
  F5: 'looped, timed out or hit the turn cap',
  F6: 'hit an environment or setup error',
  F7: 'made off-scope edits',
};

function spellOut(text: string): string {
  return text.replace(/\bF[1-7]\b/g, (code) => `${FAILURE_CODES[code]} (${code})`);
}

function list(items: string[]): string {
  if (items.length <= 1) return items.join('');
  return `${items.slice(0, -1).join(', ')} and ${items[items.length - 1]}`;
}

export function explainGate(d: {
  candidate: string;
  verdict: 'promote' | 'reject';
  reasons: string[];
  regressions: string[];
}): string {
  const parts: string[] = [];
  if (d.verdict === 'promote') {
    parts.push(`The gate promoted ${d.candidate}.`);
  } else {
    parts.push(`The gate rejected ${d.candidate}.`);
    if (d.regressions.length > 0) {
      const noun = d.regressions.length === 1 ? 'task' : 'tasks';
      parts.push(`It did worse on ${d.regressions.length} ${noun}: ${list(d.regressions)}.`);
    }
  }
  if (d.reasons.length > 0) {
    const reasons = d.reasons.map((r) => spellOut(r).replace(/[.\s]+$/, ''));
    parts.push(`Reasons: ${reasons.join('; ')}.`);
  }
  return parts.join(' ');
}

export function explainSuspect(s: {
  setupId: string | null;
  or?: number;
  p?: number;
  n: number;
  reason: string;
}): string {
  const reason = spellOut(s.reason).replace(/[.\s]+$/, '');
  if (s.setupId === null) {
    return `No setup stands out. ${reason}.`;
  }
  const stats: string[] = [`across ${s.n} runs`];
  if (s.or !== undefined) stats.push(`odds ratio ${s.or}`);
  if (s.p !== undefined) stats.push(`p = ${s.p}`);
  return `${s.setupId} is a suspect, based on observational data (${stats.join(', ')}). It is a lead to check, not proof of cause. ${reason}.`;
}
EOF
cat > tests/explain.test.ts <<'EOF'
import { expect, test } from 'bun:test';
import { explainGate, explainSuspect } from '../src/cli/explain';

test('rejection names each regressed task and spells out codes', () => {
  const t = explainGate({ candidate: 'c1', verdict: 'reject', reasons: ['F1 on 3 runs'], regressions: ['task-a', 'task-b'] });
  expect(t).toContain('rejected');
  expect(t).toContain('task-a');
  expect(t).toContain('task-b');
  expect(t).toContain('edited existing tests');
});

test('promotion', () => {
  expect(explainGate({ candidate: 'c1', verdict: 'promote', reasons: [], regressions: [] })).toContain('promoted c1');
});

test('suspect wording', () => {
  const t = explainSuspect({ setupId: 'B', or: 2, p: 0.01, n: 40, reason: 'F2 clusters here' });
  expect(t).toContain('suspect');
  expect(t).toContain('observational');
  expect(t.toLowerCase()).not.toContain('worse');
  expect(t).toContain('never ran tests');
});

test('null setup', () => {
  const t = explainSuspect({ setupId: null, n: 10, reason: 'too few runs' });
  expect(t).toContain('No setup stands out');
  expect(t).toContain('too few runs');
});
EOF
bun test tests/explain.test.ts 2>&1 | tail -8; bun run typecheck 2>&1 | tail -3

